CREATE TABLE CUSTOMERS (CUSTOMER_ID NUMBER GENERATED ALWAS AS IDENTIFY PRIMARY KEY, EMAIL VARCHAR2(255) UNIQUE NOT NULL, FULL_NAME VARCHAR2(255) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP);
CREATE TABLE ORDERS (ORDER_ID NUMBER GENERATED ALWAYS AS IDENTIFY PRIMARY KEY, CUSTOMER_ID NUMBER NOT NULL, TOTAL_AMOUNT NUMBER(10,2) NOT NULL, STATUS VARCHAE2(20) DEFAULT 'PENDING', ORACLE_TX_ID VARCHAR2(100), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP, CONSTRAINT FK_ORDERS_CUSTOMER FOREIGN KEY (CUSTOMER_ID) REFERENCES CUSTOMERS(CUSTOMER_ID));
CREATE TABLE ORDER_ITEMS (ITEM_ID NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, ORDER_ID NUMBER NOT NULL, PRODUCT_SKU VARCHAR2(50) NOT NULL, QUANTITY NUMBER NOT NULL, UNIT_PRICE NUMBER(10,2) NOT NULL, CONSTRAINT FK_ITEMS_ORDER FOREIGN KEY (ORDER_ID) REFERENCES ORDERS( ORDER_ID));
